func itDoc(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells) int32 {
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	if o != 0 {
		return 100 + o
	}
	return pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
}

func itM(emonT *testing.T, rows []byte, pos int32, e int32, line int32) int32 {
	// M name file n obj,x0,y0,x1,y1,skewed ... : the placements, in the order the content draws them
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var fs int32 = itStart(rows, pos, e, 2)
	var fe int32 = itEnd(rows, fs, e)
	var n int32 = itInt(rows, pos, e, 3)
	var k int32 = 0
	var p int32 = 0
	var q int32 = 0
	port.AssertEqAt(emonT, itDoc(port.SrcOfBlob(port.TestFileSpan(rows, fs, fe)), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx), 0, "the page runs", line)
	port.AssertEqAt(emonT, evidence.ImCount(im), n, "the number of placements", line)
	if evidence.ImCount(im) == n {
		for k < n {
			p = itStart(rows, pos, e, 4+k)
			q = itEnd(rows, p, e)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfObj()), itCint(rows, p, q, 0), "the image object", line)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfX0()), itCint(rows, p, q, 1), "x0 in page space", line)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfY0()), itCint(rows, p, q, 2), "y0 in page space", line)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfX1()), itCint(rows, p, q, 3), "x1 in page space", line)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfY1()), itCint(rows, p, q, 4), "y1 in page space", line)
			port.AssertEqAt(emonT, evidence.ImGet(im, k, evidence.MfSkewed()), itCint(rows, p, q, 5), "skewed", line)
			k += 1
		}
	}
	return 0
}

func itRows(emonT *testing.T, rows []byte) int32 {
	// Check every row; answers how many were checked.
	var n int32 = port.BlobLen(rows)
	var pos int32 = 0
	var line int32 = 0
	var e int32 = 0
	var kind int32 = 0
	var checked int32 = 0
	for pos < n {
		line += 1
		e = itNl(rows, pos)
		if (pos < e) && (port.BlobU8(rows, pos) != 35) {
			kind = port.BlobU8(rows, pos)
			checked += 1
			if kind == 68 {
				itD(emonT, rows, pos, e, line)
			}
			if kind == 80 {
				itP(emonT, rows, pos, e, line)
			}
			if kind == 82 {
				itR(emonT, rows, pos, e, line)
			}
			if kind == 79 {
				itO(emonT, rows, pos, e, line)
			}
			if kind == 88 {
				itX(emonT, rows, pos, e, line)
			}
			if kind == 73 {
				itI(emonT, rows, pos, e, line)
			}
			if kind == 77 {
				itM(emonT, rows, pos, e, line)
			}
		}
		pos = e + 1
	}
	return checked
}

func TestAssetRows(emonT *testing.T) {
	port.AssertThat(emonT, itRows(emonT, port.TestFile("assets/rows.txt")) > 100, "every row of test/assets/rows.txt is checked")
}

func itPaint(v int32) int32 {
	// A bilevel host pixel (here any byte): 0 paints, anything on the high side does not (1-bit: v >> 7).
	if v < 128 {
		return 255
	}
	return 0
}

