func TestASixteenBitSampleReducesByTheStatedRule(emonT *testing.T) {
	// (v * 255 + 32767) / 65535: 0 -> 0, 128 -> 0, 129 -> 1, 32767 -> 127, 32768 -> 128, 65535 -> 255.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var smp *port.Cells = port.NewCells()
	var dmi *port.Cells = port.NewCells()
	var dms *port.Cells = port.NewCells()
	var sh int32 = 0
	var src *port.Src = port.SrcOfBlob(port.TestFile("assets/flate-rgb16.pdf"))
	port.AssertEq(emonT, pdfdoc.PdOpen(src, ar, dc, a, b, st), 0, "the file opens")
	sh = pdfdoc.PdGet(src, ar, dc, a, b, st, 5)
	port.AssertEq(emonT, pdfimage.PiInfo(src, ar, dc, a, b, st, out, im, sh, 5), 0, "the image is read")
	port.AssertEq(emonT, pdfimage.PiGet(im, pdfimage.PiFW()), 17, "its width")
	port.AssertEq(emonT, pdfimage.PiGet(im, pdfimage.PiFH()), 11, "its height")
	port.AssertEq(emonT, pdfimage.PiSamples(src, ar, dc, a, b, st, im, sh, smp), 0, "the samples decode")
	port.AssertEq(emonT, port.CellsLen(smp), (17*11)*6, "six bytes a pixel")
	var i int32 = 0
	for i < 6 {
		port.CellsSet(smp, i, 0)
		i += 1
	}
	port.CellsSet(smp, 0, 0)
	port.CellsSet(smp, 1, 128)
	port.CellsSet(smp, 2, 0)
	port.CellsSet(smp, 3, 129)
	port.CellsSet(smp, 4, 127)
	port.CellsSet(smp, 5, 255)
	pdfimage.PiView(im, 0)
	var pic *port.Bitmap = port.BitmapNew(17, 11, 3)
	var al *port.Bitmap = port.BitmapNew(17, 11, 1)
	port.AssertEq(emonT, pdfimage.PiPixels(im, smp, pic, dmi, dms, pic, 0, 0, pic, al), 0, "the pixels are made")
	port.AssertEq(emonT, port.BitmapU8(pic, 0, 0, 0), 0, "0 is 0")
	port.AssertEq(emonT, port.BitmapU8(pic, 0, 0, 1), 1, "129 is 1")
	port.AssertEq(emonT, port.BitmapU8(pic, 0, 0, 2), 127, "32767 is 127")
}

